{{-- Lista de aniversariantes por dia ($rows de BirthdayService::month). Gestores e professores veem a idade que a pessoa faz. --}}
@php($weekdays = ['dom', 'seg', 'ter', 'qua', 'qui', 'sex', 'sáb'])
<div class="card list-card birthday-list">@forelse($rows as $row)<div class="list-row {{ $row['today'] ? 'is-today' : '' }}"><span class="birthday-day">{{ sprintf('%02d', $row['day']) }}<small>{{ $weekdays[$row['date']->dayOfWeek] }}</small></span><span class="birthday-who"><x-person-photo :person="$row['person']" /><span><strong>{{ $row['person']->social_name ?: $row['person']->full_name }}</strong><small>{{ $row['context'] }}</small></span></span>@if($row['today'])<span class="birthday-tag is-today">Hoje 🎂</span>@else<span class="birthday-tag">faz {{ $row['age'] }}</span>@endif</div>@empty<div class="empty-state"><p>{{ $empty ?? 'Nenhum aniversariante neste mês.' }}</p></div>@endforelse</div>
